from more_itertools.recipes import is_prime

def test_small_values_match_reference():
    ref = {n for n in range(2, 2000) if all(n % d for d in range(2, int(n**0.5) + 1))}
    assert {n for n in range(2000) if is_prime(n)} == ref

def test_large_known_primes_and_composites():
    assert is_prime(18_446_744_073_709_551_557)
    assert is_prime(1000000007)
    assert not is_prime(3 * 13)
    assert not is_prime(2**64 + 1)
    assert not is_prime(561 * 1000003)

def test_random_large_composites_rejected():
    for p in [1000000007, 1000000009]:
        for q in [1000000021, 998244353]:
            assert not is_prime(p * q)

import logging
from tenacity import Retrying, stop_after_attempt, before_log, after_log, before_sleep_log

class Custom:
    def __init__(self):
        self.calls = []
    def log(self, level, msg, *args, **kwargs):
        self.calls.append((level, msg))

def test_custom_logger_receives_before_after_sleep_calls():
    c = Custom()
    r = Retrying(stop=stop_after_attempt(2), before=before_log(c, logging.INFO), after=after_log(c, logging.INFO), before_sleep=before_sleep_log(c, logging.INFO), reraise=True, sleep=lambda s: None)
    try:
        r(lambda: 1 / 0)
    except ZeroDivisionError:
        pass
    assert len(c.calls) >= 3

from fastapi import APIRouter
from fastapi.routing import RouteContext, iter_route_contexts

def test_probe_route_context_basic():
    r = APIRouter()

    @r.get('/x')
    def f():
        return {}

    ctxs = list(iter_route_contexts(r.routes))
    assert len(ctxs) == 1
    assert isinstance(ctxs[0], RouteContext)
    assert ctxs[0].path == '/x'
    assert ctxs[0].original_route is r.routes[0]

