from typing import Annotated

from pydantic import StringConstraints, TypeAdapter, ValidationError


def test_ascii_only_rejects_non_ascii():
    ta = TypeAdapter(Annotated[str, StringConstraints(ascii_only=True)])
    try:
        ta.validate_python('caf\xe9')
    except ValidationError as e:
        assert e.errors()[0]['type'] == 'string_not_ascii'
    else:
        raise AssertionError('non-ASCII input was accepted')

